  "check_pending",
  "read_chat",
  "read_chat_debug",
  "send_chat",
  "approve",
  "git_status",
  "git_log",
  "git_diff",
  "git_checkpoint",
  "git_push",
  "screenshot",
  "artifact_register",
  "artifact_list"
